			{
				elems.add(LineComponent.builder()
					.leftColor(Color.WHITE)
					.left("Golpar: ")
					.rightColor(plugin.getTotalGolpar() >= (config.overloads() * 3) ? Color.GREEN : Color.WHITE)
					.right(plugin.getTotalGolpar() + "/" + (config.overloads() * 3))
